import {
    BaseColor,
    Camera,
    component,
    Devices,
    DirectionalLight,
    GlobalAmbientLight,
    InputPlugin,
    lookAtRotation,
    Materials,
    MeshInstance,
    MeshMaterial,
    type Plugin,
    StandardMaterial,
    StandardRenderer,
    type System,
    Transform,
    type World,
} from "@dylanebert/shallot";

/** The one cube; white until Space is pressed, then green for good. */
export const ColorCube = component("ColorCube", {});

export const WHITE = [1, 1, 1, 1] as const;
export const GREEN = [0.05, 0.8, 0.1, 1] as const;

function makeScene(world: World): void {
    const ambient = world.resource(GlobalAmbientLight);
    ambient.color = 0xd8e4ff;
    ambient.brightness = 380;

    const sun = world.create();
    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 1, -2, -0.35) });
    world.add(sun, DirectionalLight, { color: 0xffffff, illuminance: 6000 });

    const camera = world.create();
    world.add(camera, Camera, { clearColor: 0x191816 });
    world.add(camera, StandardRenderer);
    world.add(camera, Transform, {
        translation: [3, 2.2, 4],
        rotation: lookAtRotation(3, 2.2, 4, 0, 0, 0),
    });

    const material = world
        .resource(Materials)
        .add(StandardMaterial({ baseColor: [1, 1, 1, 1], perceptualRoughness: 0.5 }));
    const cube = world.create();
    world.add(cube, MeshInstance);
    world.add(cube, MeshMaterial, material);
    world.add(cube, BaseColor, { color: [...WHITE] });
    world.add(cube, Transform);
    world.add(cube, ColorCube);
}

const TurnGreenOnSpace: System = {
    name: "ColorCube/TurnGreenOnSpace",
    group: "setup",
    update(world: World): void {
        const devices = world.resource(Devices);
        if (!devices.enabled || !devices.keys.pressed.has("Space")) return;
        for (const cube of world.query([ColorCube]))
            world.add(cube, BaseColor, { color: [...GREEN] });
    },
};

export const ColorCubePlugin: Plugin = {
    name: "ColorCube",
    components: [ColorCube],
    dependencies: [InputPlugin],
    initialize: makeScene,
    systems: [TurnGreenOnSpace],
};

import { expect, test } from "bun:test";
import { BaseColor, createApp, pressKey, releaseKey } from "@dylanebert/shallot";
import { ColorCube, ColorCubePlugin, GREEN, WHITE } from "./index";

const close = (color: ArrayLike<number>) => Array.from(color, (v) => Math.fround(v));
const f32 = (color: readonly number[]) => color.map((v) => Math.fround(v));

test("the cube is white, turns green on the Space press step, and stays green", async () => {
    const app = await createApp({ defaults: false, plugins: [ColorCubePlugin] });
    try {
        const w = app.world;
        const cubes = [...w.query([ColorCube])];
        expect(cubes).toHaveLength(1);
        const cube = cubes[0]!;
        const color = () => close(w.get(cube, BaseColor)!.color);

        expect(color()).toEqual(f32(WHITE));
        w.step(1 / 60);
        pressKey(w, "KeyA");
        w.step(1 / 60);
        expect(color()).toEqual(f32(WHITE));

        pressKey(w, "Space");
        w.step(1 / 60);
        expect(color()).toEqual(f32(GREEN));

        releaseKey(w, "Space");
        for (let i = 0; i < 10; i++) w.step(1 / 60);
        expect(color()).toEqual(f32(GREEN));
    } finally {
        app.dispose();
    }
});

